1	/**
2	 * Event store แบบต่อท้ายอย่างเดียว (append-only)
3	 *
4	 * เก็บเป็นไฟล์ JSON Lines หนึ่งบรรทัดต่อหนึ่งเหตุการณ์
5	 * ไม่มีคำสั่งแก้ไขหรือลบ — ตามข้อกำหนด REQ-40
6	 *
7	 * ผลที่ตามมาซึ่งสำคัญต่อระบบทั้งหมด:
8	 *   สถานะปัจจุบันและตัวเลขทุกตัวที่ระบบรายงาน ไม่ได้ถูกเก็บไว้ที่ไหน
9	 *   แต่ถูก "คำนวณใหม่จากเหตุการณ์ทั้งหมด" ทุกครั้งที่มีการเรียกดู
10	 */
11	
12	import fs from 'node:fs';
13	import path from 'node:path';
14	import { fileURLToPath } from 'node:url';
15	import type { DomainEvent } from '../domain/events.ts';
16	
17	const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
18	const DATA_DIR = path.join(ROOT, 'data');
19	const LOG_PATH = path.join(DATA_DIR, 'events.jsonl');
20	
21	export function eventLogPath(): string {
22	  return LOG_PATH;
23	}
24	
25	/** อ่านเหตุการณ์ทั้งหมดตามลำดับที่บันทึก */
26	export function loadEvents(): DomainEvent[] {
27	  if (!fs.existsSync(LOG_PATH)) return [];
28	  return fs
29	    .readFileSync(LOG_PATH, 'utf8')
30	    .split('\n')
31	    .map((l) => l.trim())
32	    .filter(Boolean)
33	    .map((l) => JSON.parse(l) as DomainEvent);
34	}
35	
36	/** เหตุการณ์ทั้งหมดของการจองหนึ่งรายการ เรียงตามเวลา (REQ-41) */
37	export function loadEventsFor(bookingId: string): DomainEvent[] {
38	  return loadEvents().filter((e) => e.bookingId === bookingId);
39	}
40	
41	/** บันทึกเหตุการณ์ใหม่ต่อท้าย — ไม่มีทางแก้หรือลบของเดิม */
42	export function appendEvent(event: DomainEvent): void {
43	  fs.mkdirSync(DATA_DIR, { recursive: true });
44	  fs.appendFileSync(LOG_PATH, JSON.stringify(event) + '\n', 'utf8');
45	}
46	
47	export function appendEvents(events: DomainEvent[]): void {
48	  for (const e of events) appendEvent(e);
49	}
50	
51	/** ใช้เฉพาะตอน seed ข้อมูลตั้งต้นและในเทสเท่านั้น ไม่ใช่ส่วนหนึ่งของ API */
52	export function resetStore(events: DomainEvent[] = []): void {
53	  fs.mkdirSync(DATA_DIR, { recursive: true });
54	  fs.writeFileSync(LOG_PATH, events.map((e) => JSON.stringify(e)).join('\n') + (events.length ? '\n' : ''), 'utf8');
55	}
56

